53: const (
54: 	controllerName      = "kustomize-controller"
55: 	controllerGroup     = "kustomize.toolkit.fluxcd.io"
56: 	mask                = "**SOPS**"
57: 	dockercfgSecretType = "kubernetes.io/dockerconfigjson"
58: 	typeField           = "type"
59: 	dataField           = "data"
60: 	stringDataField     = "stringData"
61: )
62: 
63: var defaultTimeout = 80 * time.Second
64: 
65: // Builder builds yaml manifests
66: // It retrieves the kustomization object from the k8s cluster
67: // and overlays the manifests with the resources specified in the resourcesPath
68: type Builder struct {
69: 	client            client.WithWatch
70: 	restMapper        meta.RESTMapper
71: 	name              string
72: 	namespace         string
73: 	resourcesPath     string
74: 	kustomizationFile string
75: 	ignore            []string
76: 	// mu is used to synchronize access to the kustomization file
77: 	mu            sync.Mutex
78: 	action        kustomize.Action
79: 	kustomization *kustomizev1.Kustomization
80: 	timeout       time.Duration
81: 	spinner       *yacspin.Spinner
82: 	dryRun        bool
83: }
84: 
85: // BuilderOptionFunc is a function that configures a Builder
86: type BuilderOptionFunc func(b *Builder) error
87: 
88: // WithKustomizationFile sets the kustomization file
89: func WithKustomizationFile(file string) BuilderOptionFunc {
90: 	return func(b *Builder) error {
91: 		b.kustomizationFile = file
92: 		return nil
93: 	}
94: }
95: 
96: // WithTimeout sets the timeout for the builder
97: func WithTimeout(timeout time.Duration) BuilderOptionFunc {
98: 	return func(b *Builder) error {
99: 		b.timeout = timeout
100: 		return nil
101: 	}
102: }
103: 
104: func WithProgressBar() BuilderOptionFunc {
105: 	return func(b *Builder) error {
106: 		// Add a spiner
107: 		cfg := yacspin.Config{
108: 			Frequency:       100 * time.Millisecond,
109: 			CharSet:         yacspin.CharSets[59],
110: 			Suffix:          "Kustomization diffing...",
111: 			SuffixAutoColon: true,
112: 			Message:         "running dry-run",
113: 			StopCharacter:   "✓",
114: 			StopColors:      []string{"fgGreen"},
115: 		}
116: 		spinner, err := yacspin.New(cfg)
117: 		if err != nil {
118: 			return fmt.Errorf("failed to create spinner: %w", err)
119: 		}
120: 		b.spinner = spinner
121: 
122: 		return nil
123: 	}
124: }
125: 
126: // WithClientConfig sets the client configuration
127: func WithClientConfig(rcg *genericclioptions.ConfigFlags, clientOpts *runclient.Options) BuilderOptionFunc {
128: 	return func(b *Builder) error {
129: 		kubeClient, err := utils.KubeClient(rcg, clientOpts)
130: 		if err != nil {
131: 			return err
132: 		}
133: 
134: 		restMapper, err := rcg.ToRESTMapper()
135: 		if err != nil {
136: 			return err
137: 		}
138: 		b.client = kubeClient
139: 		b.restMapper = restMapper
140: 		b.namespace = *rcg.Namespace
141: 		return nil
142: 	}
143: }
144: 
145: // WithNamespace sets the namespace
146: func WithNamespace(namespace string) BuilderOptionFunc {
147: 	return func(b *Builder) error {
148: 		b.namespace = namespace
149: 		return nil
150: 	}
151: }
152: 
153: // WithDryRun sets the dry-run flag
154: func WithDryRun(dryRun bool) BuilderOptionFunc {
155: 	return func(b *Builder) error {
156: 		b.dryRun = dryRun
157: 		return nil
158: 	}
159: }
160: 
161: // WithIgnore sets ignore field
162: func WithIgnore(ignore []string) BuilderOptionFunc {
163: 	return func(b *Builder) error {
164: 		b.ignore = ignore
165: 		return nil
166: 	}
167: }
168: 
169: // NewBuilder returns a new Builder
170: // It takes a kustomization name and a path to the resources
171: // It also takes a list of BuilderOptionFunc to configure the builder
172: // One of the options is WithClientConfig, that must be provided for the builder to work
173: // with the k8s cluster
174: // One other option is WithKustomizationFile, that must be provided for the builder to work
175: // with a local kustomization file. If the kustomization file is not provided, the builder
176: // will try to retrieve the kustomization object from the k8s cluster.
177: // WithDryRun sets the dry-run flag, and needs to be provided if the builder is used for
178: // a dry-run. This flag works in conjunction with WithKustomizationFile, because the
179: // kustomization object is not retrieved from the k8s cluster when the dry-run flag is set.
180: func NewBuilder(name, resources string, opts ...BuilderOptionFunc) (*Builder, error) {
181: 	b := &Builder{
182: 		name:          name,
183: 		resourcesPath: resources,
184: 	}
185: 
186: 	for _, opt := range opts {
187: 		if err := opt(b); err != nil {
188: 			return nil, err
189: 		}
190: 	}
191: 
192: 	if b.timeout == 0 {
193: 		b.timeout = defaultTimeout
194: 	}
195: 
196: 	if b.dryRun && b.kustomizationFile == "" {
197: 		return nil, fmt.Errorf("kustomization file is required for dry-run")
198: 	}
199: 
200: 	if !b.dryRun && b.client == nil {
201: 		return nil, fmt.Errorf("client is required for live run")
202: 	}
203: 
204: 	return b, nil
205: }
206: 
207: func (b *Builder) resolveKustomization(liveKus *kustomizev1.Kustomization) (k *kustomizev1.Kustomization, err error) {
208: 	// local kustomization file takes precedence over live kustomization
209: 	if b.kustomizationFile != "" {
210: 		k, err = b.unMarshallKustomization()
211: 		if err != nil {
212: 			return
213: 		}
214: 		if !b.dryRun && liveKus != nil && liveKus.Status.Inventory != nil {
215: 			// merge the live kustomization status with the local kustomization in order to get the
216: 			// live resources status
217: 			k.Status = *liveKus.Status.DeepCopy()
218: 		}
219: 	} else {
220: 		k = liveKus
221: 	}
222: 	return
223: }
224: 
225: func (b *Builder) getKustomization(ctx context.Context) (*kustomizev1.Kustomization, error) {
226: 	liveKus := &kustomizev1.Kustomization{}
227: 	namespacedName := types.NamespacedName{
228: 		Namespace: b.namespace,
229: 		Name:      b.name,
230: 	}
231: 	err := b.client.Get(ctx, namespacedName, liveKus)
232: 	if err != nil {
233: 		return nil, err
234: 	}
235: 
236: 	return liveKus, nil
237: }
238: 
239: // Build builds the yaml manifests from the kustomization object
240: // and overlays the manifests with the resources specified in the resourcesPath
241: // It expects a kustomization.yaml file in the resourcesPath, and it will
242: // generate a kustomization.yaml file if it doesn't exist
243: func (b *Builder) Build() ([]*unstructured.Unstructured, error) {
244: 	m, err := b.build()
245: 	if err != nil {
246: 		return nil, err
247: 	}
248: 
249: 	resources, err := m.AsYaml()
250: 	if err != nil {
251: 		return nil, fmt.Errorf("kustomize build failed: %w", err)
252: 	}
253: 
254: 	objects, err := ssa.ReadObjects(bytes.NewReader(resources))
255: 	if err != nil {
256: 		return nil, fmt.Errorf("kustomize build failed: %w", err)
257: 	}
258: 
259: 	if m := b.kustomization.Spec.CommonMetadata; m != nil {
260: 		ssa.SetCommonMetadata(objects, m.Labels, m.Annotations)
261: 	}
262: 
263: 	return objects, nil
264: }
265: 
266: func (b *Builder) build() (m resmap.ResMap, err error) {
267: 	ctx, cancel := context.WithTimeout(context.Background(), b.timeout)
268: 	defer cancel()
269: 
270: 	// Get the kustomization object
271: 	liveKus := &kustomizev1.Kustomization{}
272: 	if !b.dryRun {
273: 		liveKus, err = b.getKustomization(ctx)
274: 		if err != nil {
275: 			return nil, fmt.Errorf("failed to get kustomization object: %w", err)
276: 		}
277: 	}
278: 	k, err := b.resolveKustomization(liveKus)
279: 	if err != nil {
280: 		err = fmt.Errorf("failed to get kustomization object: %w", err)
281: 		return
282: 	}
283: 
284: 	// store the kustomization object
285: 	b.kustomization = k
286: 
287: 	// generate kustomization.yaml if needed
288: 	action, er := b.generate(*k, b.resourcesPath)
289: 	if er != nil {
290: 		errf := kustomize.CleanDirectory(b.resourcesPath, action)
291: 		err = fmt.Errorf("failed to generate kustomization.yaml: %w", fmt.Errorf("%v %v", er, errf))
292: 		return
293: 	}
294: 
295: 	b.action = action
296: 
297: 	defer func() {
298: 		errf := b.Cancel()
299: 		if err == nil {
300: 			err = errf
301: 		}
302: 	}()
303: 
304: 	// build the kustomization
305: 	m, err = b.do(ctx, *k, b.resourcesPath)
306: 	if err != nil {
307: 		return
308: 	}
309: 
310: 	for _, res := range m.Resources() {
311: 		// set owner labels
312: 		err = b.setOwnerLabels(res)
313: 		if err != nil {
314: 			return
315: 		}
316: 
317: 		// make sure secrets are masked
318: 		err = maskSopsData(res)
319: 		if err != nil {
320: 			return
321: 		}
322: 	}
323: 
324: 	return
325: 
326: }
327: 
328: func (b *Builder) unMarshallKustomization() (*kustomizev1.Kustomization, error) {
329: 	data, err := os.ReadFile(b.kustomizationFile)
330: 	if err != nil {
331: 		return nil, fmt.Errorf("failed to read kustomization file %s: %w", b.kustomizationFile, err)
332: 	}
333: 	k := &kustomizev1.Kustomization{}
334: 	decoder := k8syaml.NewYAMLOrJSONDecoder(bytes.NewBuffer(data), len(data))
335: 	// check for kustomization in yaml with the same name and namespace
336: 	for {
337: 		err = decoder.Decode(k)
338: 		if err != nil {
339: 			if err == io.EOF {
340: 				return nil, fmt.Errorf("failed find kustomization with name '%s' and namespace '%s' in file '%s'",
341: 					b.name, b.namespace, b.kustomizationFile)
342: 			} else {
343: 				return nil, fmt.Errorf("failed to unmarshall kustomization file %s: %w", b.kustomizationFile, err)
344: 			}
345: 		}
346: 
347: 		if strings.HasPrefix(k.APIVersion, kustomizev1.GroupVersion.Group+"/") &&
348: 			k.Kind == kustomizev1.KustomizationKind &&
349: 			k.Name == b.name &&
350: 			(k.Namespace == b.namespace || k.Namespace == "") {
351: 			break
352: 		}
353: 	}
354: 	return k, nil
355: }
356: 
357: func (b *Builder) generate(kustomization kustomizev1.Kustomization, dirPath string) (kustomize.Action, error) {
358: 	data, err := runtime.DefaultUnstructuredConverter.ToUnstructured(&kustomization)
359: 	if err != nil {
360: 		return "", err
361: 	}
362: 
363: 	// a scanner will be used down the line to parse the list
364: 	// so we have to make sure to unclude newlines
365: 	ignoreList := strings.Join(b.ignore, "\n")
366: 	gen := kustomize.NewGeneratorWithIgnore("", ignoreList, unstructured.Unstructured{Object: data})
367: 
368: 	// acquire the lock
369: 	b.mu.Lock()
370: 	defer b.mu.Unlock()
371: 
372: 	return gen.WriteFile(dirPath, kustomize.WithSaveOriginalKustomization())
373: }
374: 
375: func (b *Builder) do(ctx context.Context, kustomization kustomizev1.Kustomization, dirPath string) (resmap.ResMap, error) {
376: 	fs := filesys.MakeFsOnDisk()
377: 
378: 	// acuire the lock
379: 	b.mu.Lock()
380: 	defer b.mu.Unlock()
381: 
382: 	m, err := kustomize.Build(fs, dirPath)
383: 	if err != nil {
384: 		return nil, fmt.Errorf("kustomize build failed: %w", err)
385: 	}
386: 
387: 	for _, res := range m.Resources() {
388: 		// run variable substitutions
389: 		if kustomization.Spec.PostBuild != nil {
390: 			data, err := runtime.DefaultUnstructuredConverter.ToUnstructured(&kustomization)
391: 			if err != nil {
392: 				return nil, err
393: 			}
394: 			outRes, err := kustomize.SubstituteVariables(ctx, b.client, unstructured.Unstructured{Object: data}, res, b.dryRun)
395: 			if err != nil {
396: 				return nil, fmt.Errorf("var substitution failed for '%s': %w", res.GetName(), err)
397: 			}
398: 
399: 			if outRes != nil {
400: 				_, err = m.Replace(res)
401: 				if err != nil {
402: 					return nil, err
403: 				}
404: 			}
405: 		}
406: 	}
407: 
408: 	return m, nil
409: }
410: 
411: func (b *Builder) setOwnerLabels(res *resource.Resource) error {
412: 	labels := res.GetLabels()
413: 
414: 	labels[controllerGroup+"/name"] = b.kustomization.GetName()
415: 	labels[controllerGroup+"/namespace"] = b.kustomization.GetNamespace()
416: 
417: 	err := res.SetLabels(labels)
418: 	if err != nil {
419: 		return err
420: 	}
421: 
422: 	return nil
423: }
424: 
425: func maskSopsData(res *resource.Resource) error {
426: 	// sopsMess is the base64 encoded mask
427: 	sopsMess := base64.StdEncoding.EncodeToString([]byte(mask))
428: 
429: 	if res.GetKind() == "Secret" {
430: 		// get both data and stringdata maps as a secret can have both
431: 		dataMap := res.GetDataMap()
432: 		stringDataMap := getStringDataMap(res)
433: 		asYaml, err := res.AsYAML()
434: 		if err != nil {
435: 			return fmt.Errorf("failed to mask secret %s sops data: %w", res.GetName(), err)
436: 		}
437: 
438: 		// delete any sops data as we don't want to expose it
439: 		// assume that both data and stringdata are encrypted
440: 		if bytes.Contains(asYaml, []byte("sops:")) && bytes.Contains(asYaml, []byte("mac: ENC[")) {
441: 			// delete the sops object
442: 			res.PipeE(yaml.FieldClearer{Name: "sops"})
443: 
444: 			secretType, err := res.GetFieldValue(typeField)
445: 			// If the intended type is Opaque, then it can be omitted from the manifest, since it's the default
446: 			// Ref: https://kubernetes.io/docs/concepts/configuration/secret/#opaque-secrets
447: 			if errors.As(err, &yaml.NoFieldError{}) {
448: 				secretType = "Opaque"
449: 			} else if err != nil {
450: 				return fmt.Errorf("failed to mask secret %s sops data: %w", res.GetName(), err)
451: 			}
452: 
453: 			if v, ok := secretType.(string); ok && v == dockercfgSecretType {
454: 				// if the secret is a json docker config secret, we need to mask the data with a json object
455: 				err := maskDockerconfigjsonSopsData(dataMap, true)
456: 				if err != nil {
457: 					return fmt.Errorf("failed to mask secret %s sops data: %w", res.GetName(), err)
458: 				}
459: 
460: 				err = maskDockerconfigjsonSopsData(stringDataMap, false)
461: 				if err != nil {
462: 					return fmt.Errorf("failed to mask secret %s sops data: %w", res.GetName(), err)
463: 				}
464: 
465: 			} else {
466: 				for k := range dataMap {
467: 					dataMap[k] = sopsMess
468: 				}
469: 
470: 				for k := range stringDataMap {
471: 					stringDataMap[k] = mask
472: 				}
473: 			}
474: 		} else {
475: 			err := maskBase64EncryptedSopsData(dataMap, sopsMess)
476: 			if err != nil {
477: 				return fmt.Errorf("failed to mask secret %s sops data: %w", res.GetName(), err)
478: 			}
479: 
480: 			err = maskSopsDataInStringDataSecret(stringDataMap, sopsMess)
481: 			if err != nil {
482: 				return fmt.Errorf("failed to mask secret %s sops data: %w", res.GetName(), err)
483: 			}
484: 		}
485: 
486: 		// set the data and stringdata maps
487: 		res.SetDataMap(dataMap)
488: 
489: 		if len(stringDataMap) > 0 {
490: 			err = res.SetMapField(yaml.NewMapRNode(&stringDataMap), stringDataField)
491: 			if err != nil {
492: 				return fmt.Errorf("failed to mask secret %s sops data: %w", res.GetName(), err)
493: 			}
494: 		}
495: 	}
496: 
497: 	return nil
498: }
499: 
500: func getStringDataMap(rn *resource.Resource) map[string]string {
501: 	n, err := rn.Pipe(yaml.Lookup(stringDataField))
502: 	if err != nil {
503: 		return nil
504: 	}
505: 	result := map[string]string{}
506: 	_ = n.VisitFields(func(node *yaml.MapNode) error {
507: 		result[yaml.GetValue(node.Key)] = yaml.GetValue(node.Value)
508: 		return nil
509: 	})
510: 	return result
511: }
512: 
513: func maskDockerconfigjsonSopsData(dataMap map[string]string, encode bool) error {
514: 	sopsMess := struct {
515: 		Mask string `json:"mask"`
516: 	}{
517: 		Mask: mask,
518: 	}
519: 
520: 	maskJson, err := json.Marshal(sopsMess)
521: 	if err != nil {
522: 		return err
523: 	}
524: 
525: 	if encode {
526: 		for k := range dataMap {
527: 			dataMap[k] = base64.StdEncoding.EncodeToString(maskJson)
528: 		}
529: 		return nil
530: 	}
531: 
532: 	for k := range dataMap {
533: 		dataMap[k] = string(maskJson)
534: 	}
535: 
536: 	return nil
537: }
538: 
539: func maskBase64EncryptedSopsData(dataMap map[string]string, mask string) error {
540: 	for k, v := range dataMap {
541: 		data, err := base64.StdEncoding.DecodeString(v)
542: 		if corruptErr := base64.CorruptInputError(0); errors.As(err, &corruptErr) {
543: 			return corruptErr
544: 		}
545: 
546: 		if bytes.Contains(data, []byte("sops")) && bytes.Contains(data, []byte("ENC[")) {
547: 			dataMap[k] = mask
548: 		}
549: 	}
550: 
551: 	return nil
552: }
553: 
554: func maskSopsDataInStringDataSecret(stringDataMap map[string]string, mask string) error {
555: 	for k, v := range stringDataMap {
556: 		if bytes.Contains([]byte(v), []byte("sops")) && bytes.Contains([]byte(v), []byte("ENC[")) {
557: 			stringDataMap[k] = mask
558: 		}
559: 	}
560: 
561: 	return nil
562: }
563: 
564: // Cancel cancels the build
565: // It restores a clean reprository
566: func (b *Builder) Cancel() error {
567: 	// acuire the lock
568: 	b.mu.Lock()
569: 	defer b.mu.Unlock()
570: 
571: 	err := kustomize.CleanDirectory(b.resourcesPath, b.action)
572: 	if err != nil {
573: 		return err
574: 	}
575: 
576: 	return nil
577: }
