63: var defaultTimeout = 80 * time.Second
64: 
65: // Builder builds yaml manifests
66: // It retrieves the kustomization object from the k8s cluster
67: // and overlays the manifests with the resources specified in the resourcesPath
68: type Builder struct {
69: 	client            client.WithWatch
70: 	restMapper        meta.RESTMapper
71: 	name              string
72: 	namespace         string
73: 	resourcesPath     string
74: 	kustomizationFile string
75: 	ignore            []string
76: 	// mu is used to synchronize access to the kustomization file
77: 	mu            sync.Mutex
78: 	action        kustomize.Action
