17: package kustomization
18: 
19: import (
20: 	"fmt"
21: 	"os"
22: 	"path/filepath"
23: 	"strings"
24: 	"sync"
25: 
26: 	"sigs.k8s.io/kustomize/api/konfig"
27: 	"sigs.k8s.io/kustomize/api/krusty"
28: 	"sigs.k8s.io/kustomize/api/provider"
29: 	kustypes "sigs.k8s.io/kustomize/api/types"
30: 	"sigs.k8s.io/yaml"
31: 
32: 	"github.com/fluxcd/pkg/kustomize/filesys"
33: 
34: 	"github.com/fluxcd/flux2/v2/pkg/manifestgen"
35: )
36: 
37: // Generate scans the given directory for Kubernetes manifests and creates a
38: // konfig.DefaultKustomizationFileName file, including all discovered manifests
39: // as resources.
40: func Generate(options Options) (*manifestgen.Manifest, error) {
41: 	kfile := filepath.Join(options.TargetPath, konfig.DefaultKustomizationFileName())
42: 	abskfile := filepath.Join(options.BaseDir, kfile)
43: 
44: 	scan := func(base string) ([]string, error) {
45: 		var paths []string
46: 		pvd := provider.NewDefaultDepProvider()
47: 		rf := pvd.GetResourceFactory()
48: 		err := options.FileSystem.Walk(base, func(path string, info os.FileInfo, err error) error {
49: 			if err != nil {
50: 				return err
51: 			}
52: 			if path == base {
53: 				return nil
54: 			}
55: 			if info.IsDir() {
56: 				// If a sub-directory contains an existing Kustomization file, add the
57: 				// directory as a resource and do not decent into it.
58: 				for _, kfilename := range konfig.RecognizedKustomizationFileNames() {
59: 					if options.FileSystem.Exists(filepath.Join(path, kfilename)) {
60: 						paths = append(paths, path)
61: 						return filepath.SkipDir
62: 					}
63: 				}
64: 				return nil
65: 			}
66: 			fContents, err := options.FileSystem.ReadFile(path)
67: 			if err != nil {
68: 				return err
69: 			}
70: 			if _, err := rf.SliceFromBytes(fContents); err != nil {
71: 				return nil
72: 			}
73: 			paths = append(paths, path)
74: 			return nil
75: 		})
76: 		return paths, err
77: 	}
78: 
79: 	if _, err := os.Stat(abskfile); err != nil {
80: 		abs, err := filepath.Abs(filepath.Dir(abskfile))
81: 		if err != nil {
82: 			return nil, err
83: 		}
84: 
85: 		files, err := scan(abs)
86: 		if err != nil {
87: 			return nil, err
88: 		}
89: 
90: 		f, err := options.FileSystem.Create(abskfile)
91: 		if err != nil {
92: 			return nil, err
93: 		}
94: 		if err = f.Close(); err != nil {
95: 			return nil, err
96: 		}
97: 
98: 		kus := kustypes.Kustomization{
99: 			TypeMeta: kustypes.TypeMeta{
100: 				APIVersion: kustypes.KustomizationVersion,
101: 				Kind:       kustypes.KustomizationKind,
102: 			},
103: 		}
104: 
105: 		var resources []string
106: 		for _, file := range files {
107: 			relP, err := filepath.Rel(abs, file)
108: 			if err != nil {
109: 				return nil, err
110: 			}
111: 			resources = append(resources, relP)
112: 		}
113: 
114: 		kus.Resources = resources
115: 		kd, err := yaml.Marshal(kus)
116: 		if err != nil {
117: 			return nil, err
118: 		}
119: 
120: 		return &manifestgen.Manifest{
121: 			Path:    kfile,
122: 			Content: string(kd),
123: 		}, nil
124: 	}
125: 
126: 	kd, err := os.ReadFile(abskfile)
127: 	if err != nil {
128: 		return nil, err
129: 	}
130: 	return &manifestgen.Manifest{
131: 		Path:    kfile,
132: 		Content: string(kd),
133: 	}, nil
134: }
135: 
136: // kustomizeBuildMutex is a workaround for a concurrent map read and map write bug.
137: // TODO(stefan): https://github.com/kubernetes-sigs/kustomize/issues/3659
138: var kustomizeBuildMutex sync.Mutex
139: 
140: // Build takes the path to a directory with a konfig.RecognizedKustomizationFileNames,
141: // builds it, and returns the resulting manifests as multi-doc YAML. It restricts the
142: // Kustomize file system to the parent directory of the base.
143: func Build(base string) ([]byte, error) {
144: 	// TODO(hidde): drop this when consumers have moved away to BuildWithRoot.
145: 	parent := filepath.Dir(strings.TrimSuffix(base, string(filepath.Separator)))
146: 	return BuildWithRoot(parent, base)
147: }
148: 
149: // BuildWithRoot takes the path to a directory with a konfig.RecognizedKustomizationFileNames,
150: // builds it, and returns the resulting manifests as multi-doc YAML.
151: // The Kustomize file system is restricted to root.
152: func BuildWithRoot(root, base string) ([]byte, error) {
153: 	kustomizeBuildMutex.Lock()
154: 	defer kustomizeBuildMutex.Unlock()
155: 
156: 	fs, err := filesys.MakeFsOnDiskSecureBuild(root)
157: 	if err != nil {
158: 		return nil, err
159: 	}
160: 
161: 	var kfile string
162: 	for _, f := range konfig.RecognizedKustomizationFileNames() {
163: 		if kf := filepath.Join(base, f); fs.Exists(kf) {
164: 			kfile = kf
165: 			break
166: 		}
167: 	}
168: 	if kfile == "" {
169: 		return nil, fmt.Errorf("%s not found", konfig.DefaultKustomizationFileName())
170: 	}
171: 
172: 	// TODO(hidde): work around for a bug in kustomize causing it to
173: 	//  not properly handle absolute paths on Windows.
174: 	//  Convert the path to a relative path to the working directory
175: 	//  as a temporary fix:
176: 	//  https://github.com/kubernetes-sigs/kustomize/issues/2789
177: 	if filepath.IsAbs(base) {
178: 		wd, err := os.Getwd()
179: 		if err != nil {
180: 			return nil, err
181: 		}
182: 		base, err = filepath.Rel(wd, base)
183: 		if err != nil {
184: 			return nil, err
185: 		}
186: 	}
187: 
188: 	buildOptions := &krusty.Options{
189: 		LoadRestrictions: kustypes.LoadRestrictionsNone,
190: 		PluginConfig:     kustypes.DisabledPluginConfig(),
191: 	}
192: 
193: 	k := krusty.MakeKustomizer(buildOptions)
194: 	m, err := k.Run(fs, base)
195: 	if err != nil {
196: 		return nil, err
197: 	}
198: 
199: 	resources, err := m.AsYaml()
200: 	if err != nil {
201: 		return nil, err
202: 	}
203: 
204: 	return resources, nil
205: }
206: "}

