126: 	kd, err := os.ReadFile(abskfile)
127: 	if err != nil {
128: 		return nil, err
129: 	}
130: 	return &manifestgen.Manifest{
131: 		Path:    kfile,
132: 		Content: string(kd),
133: 	}, nil
134: }
