136: // kustomizeBuildMutex is a workaround for a concurrent map read and map write bug.
137: // TODO(stefan): https://github.com/kubernetes-sigs/kustomize/issues/3659
138: var kustomizeBuildMutex sync.Mutex
139: 
140: // Build takes the path to a directory with a konfig.RecognizedKustomizationFileNames,
141: // builds it, and returns the resulting manifests as multi-doc YAML. It restricts the
142: // Kustomize file system to the parent directory of the base.
143: func Build(base string) ([]byte, error) {
144: 	// TODO(hidde): drop this when consumers have moved away to BuildWithRoot.
145: 	parent := filepath.Dir(strings.TrimSuffix(base, string(filepath.Separator)))
146: 	return BuildWithRoot(parent, base)
147: }
148: 
149: // BuildWithRoot takes the path to a directory with a konfig.RecognizedKustomizationFileNames,
150: // builds it, and returns the resulting manifests as multi-doc YAML.
151: // The Kustomize file system is restricted to root.
152: func BuildWithRoot(root, base string) ([]byte, error) {
153: 	kustomizeBuildMutex.Lock()
154: 	defer kustomizeBuildMutex.Unlock()
155: 
156: 	fs, err := filesys.MakeFsOnDiskSecureBuild(root)
157: 	if err != nil {
158: 		return nil, err
159: 	}
160: 
161: 	var kfile string
162: 	for _, f := range konfig.RecognizedKustomizationFileNames() {
163: 		if kf := filepath.Join(base, f); fs.Exists(kf) {
164: 			kfile = kf
165: 			break
166: 		}
167: 	}
168: 	if kfile == "" {
169: 		return nil, fmt.Errorf("%s not found", konfig.DefaultKustomizationFileName())
170: 	}
171: 
172: 	// TODO(hidde): work around for a bug in kustomize causing it to
173: 	//  not properly handle absolute paths on Windows.
174: 	//  Convert the path to a relative path to the working directory
175: 	//  as a temporary fix:
176: 	//  https://github.com/kubernetes-sigs/kustomize/issues/2789
177: 	if filepath.IsAbs(base) {
178: 		wd, err := os.Getwd()
179: 		if err != nil {
180: 			return nil, err
181: 		}
182: 		base, err = filepath.Rel(wd, base)
183: 		if err != nil {
184: 			return nil, err
185: 		}
186: 	}
187: 
188: 	buildOptions := &krusty.Options{
189: 		LoadRestrictions: kustypes.LoadRestrictionsNone,
190: 		PluginConfig:     kustypes.DisabledPluginConfig(),
191: 	}
192: 
193: 	k := krusty.MakeKustomizer(buildOptions)
194: 	m, err := k.Run(fs, base)
195: 	if err != nil {
196: 		return nil, err
197: 	}
198: 
199: 	resources, err := m.AsYaml()
200: 	if err != nil {
201: 		return nil, err
202: 	}
203: 
204: 	return resources, nil
205: }
