323: // semver/v3 doesn't export the regexp anymore, so shamelessly copied it over to
324: // here.
325: // https://github.com/Masterminds/semver/blob/49c09bfed6adcffa16482ddc5e5588cffff9883a/version.go#L42
326: const semVerRegex string = `v?([0-9]+)(\.[0-9]+)?(\.[0-9]+)?` +
327: 	`(-([0-9A-Za-z\-]+(\.[0-9A-Za-z\-]+)*))?` +
328: 	`(\+([0-9A-Za-z\-]+(\.[0-9A-Za-z\-]+)*))?`
329: 
330: var (
331: 	unknownVersion = semver.MustParse("v99.99.99")
332: 	semverRegex    = regexp.MustCompile(semVerRegex)
333: 	semVer         *semver.Version
334: 	semVerLock     sync.Mutex
335: )
336: 
337: // getSemver returns parsed kustomize version
338: func getSemver() (*semver.Version, error) {
339: 	verStr, err := Version(true)
340: 	if err != nil {
341: 		return nil, err
342: 	}
343: 
344: 	semverMatches := semverRegex.FindStringSubmatch(verStr)
345: 	if len(semverMatches) == 0 {
346: 		return nil, fmt.Errorf("expected string that includes semver formatted version but got: '%s'", verStr)
347: 	}
348: 
349: 	return semver.NewVersion(semverMatches[0])
350: }
351: 
352: // getSemverSafe returns parsed kustomize version;
353: // if version cannot be parsed assumes that "kustomize version" output format changed again
354: // and fallback to latest ( v99.99.99 )
355: func getSemverSafe() *semver.Version {
356: 	if semVer == nil {
357: 		semVerLock.Lock()
358: 		defer semVerLock.Unlock()
359: 
360: 		if ver, err := getSemver(); err != nil {
361: 			semVer = unknownVersion
362: 			log.Warnf("Failed to parse kustomize version: %v", err)
363: 		} else {
364: 			semVer = ver
365: 		}
366: 	}
367: 	return semVer
368: }
