370: func Version(shortForm bool) (string, error) {
371: 	executable := "kustomize"
372: 	cmdArgs := []string{"version"}
373: 	if shortForm {
374: 		cmdArgs = append(cmdArgs, "--short")
375: 	}
376: 	cmd := exec.Command(executable, cmdArgs...)
377: 	// example version output:
378: 	// long: "{Version:kustomize/v3.8.1 GitCommit:0b359d0ef0272e6545eda0e99aacd63aef99c4d0 BuildDate:2020-07-16T00:58:46Z GoOs:linux GoArch:amd64}"
379: 	// short: "{kustomize/v3.8.1  2020-07-16T00:58:46Z  }"
380: 	version, err := executil.Run(cmd)
381: 	if err != nil {
382: 		return "", fmt.Errorf("could not get kustomize version: %s", err)
383: 	}
384: 	version = strings.TrimSpace(version)
385: 	if shortForm {
386: 		// trim the curly braces
387: 		version = strings.TrimPrefix(version, "{")
388: 		version = strings.TrimSuffix(version, "}")
389: 		version = strings.TrimSpace(version)
390: 
391: 		// remove double space in middle
392: 		version = strings.ReplaceAll(version, "  ", " ")
393: 
394: 		// remove extra 'kustomize/' before version
395: 		version = strings.TrimPrefix(version, "kustomize/")
396: 
397: 	}
398: 	return version, nil
399: }
