412: func getImages(object map[string]interface{}) []Image {
413: 	var images []Image
414: 	for k, v := range object {
415: 		if array, ok := v.([]interface{}); ok {
416: 			if k == "containers" || k == "initContainers" {
417: 				for _, obj := range array {
418: 					if mapObj, isMapObj := obj.(map[string]interface{}); isMapObj {
419: 						if image, hasImage := mapObj["image"]; hasImage {
420: 							images = append(images, fmt.Sprintf("%s", image))
421: 						}
422: 					}
423: 				}
424: 			} else {
425: 				for i := range array {
426: 					if mapObj, isMapObj := array[i].(map[string]interface{}); isMapObj {
427: 						images = append(images, getImages(mapObj)...)
428: 					}
429: 				}
430: 			}
431: 		} else if objMap, ok := v.(map[string]interface{}); ok {
432: 			images = append(images, getImages(objMap)...)
