57: 		// even if the output is already in dst. We remove the node from dst to
58: 		// prevent duplicates.
59: 		if len(keys) > 1 {
60: 			_, err = dst.Pipe(yaml.ElementSetter{
61: 				Keys:   keys,
62: 				Values: v,
63: 			})
64: 			if err != nil {
65: 				return nil, err
66: 			}
67: 		}
