238: // StateDiffs will apply all required normalizations and calculate the diffs between
239: // the live and the config/desired states.
240: func StateDiffs(lives, configs []*unstructured.Unstructured, diffConfig DiffConfig) (*diff.DiffResultList, error) {
241: 	normResults, err := preDiffNormalize(lives, configs, diffConfig)
242: 	if err != nil {
243: 		return nil, fmt.Errorf("failed to perform pre-diff normalization: %w", err)
244: 	}
245: 
246: 	diffNormalizer, err := newDiffNormalizer(diffConfig.Ignores(), diffConfig.Overrides())
247: 	if err != nil {
248: 		return nil, fmt.Errorf("failed to create diff normalizer: %w", err)
249: 	}
250: 
251: 	diffOpts := []diff.Option{
252: 		diff.WithNormalizer(diffNormalizer),
253: 		diff.IgnoreAggregatedRoles(diffConfig.IgnoreAggregatedRoles()),
254: 		diff.WithStructuredMergeDiff(diffConfig.StructuredMergeDiff()),
255: 		diff.WithGVKParser(diffConfig.GVKParser()),
256: 		diff.WithManager(diffConfig.Manager()),
257: 	}
258: 
259: 	if diffConfig.Logger() != nil {
260: 		diffOpts = append(diffOpts, diff.WithLogr(*diffConfig.Logger()))
261: 	}
262: 
263: 	useCache, cachedDiff := diffConfig.DiffFromCache(diffConfig.AppName())
264: 	if useCache && cachedDiff != nil {
265: 		cached, err := diffArrayCached(normResults.Targets, normResults.Lives, cachedDiff, diffOpts...)
266: 		if err != nil {
267: 			return nil, fmt.Errorf("failed to calculate diff from cache: %w", err)
268: 		}
269: 		return cached, nil
270: 	}
271: 	array, err := diff.DiffArray(normResults.Targets, normResults.Lives, diffOpts...)
272: 	if err != nil {
273: 		return nil, fmt.Errorf("failed to calculate diff: %w", err)
274: 	}
275: 	return array, nil
276: }
277: 
278: func diffArrayCached(configArray []*unstructured.Unstructured, liveArray []*unstructured.Unstructured, cachedDiff []*v1alpha1.ResourceDiff, opts ...diff.Option) (*diff.DiffResultList, error) {
279: 	numItems := len(configArray)
280: 	if len(liveArray) != numItems {
281: 		return nil, fmt.Errorf("left and right arrays have mismatched lengths")
282: 	}
283: 
284: 	diffByKey := map[kube.ResourceKey]*v1alpha1.ResourceDiff{}
285: 	for i := range cachedDiff {
286: 		res := cachedDiff[i]
287: 		diffByKey[kube.NewResourceKey(res.Group, res.Kind, res.Namespace, res.Name)] = cachedDiff[i]
288: 	}
289: 
290: 	diffResultList := diff.DiffResultList{
291: 		Diffs: make([]diff.DiffResult, numItems),
292: 	}
293: 
294: 	for i := 0; i < numItems; i++ {
295: 		config := configArray[i]
296: 		live := liveArray[i]
297: 		resourceVersion := ""
298: 		var key kube.ResourceKey
299: 		if live != nil {
300: 			key = kube.GetResourceKey(live)
301: 			resourceVersion = live.GetResourceVersion()
302: 		} else {
303: 			key = kube.GetResourceKey(config)
304: 		}
305: 		var dr *diff.DiffResult
306: 		if cachedDiff, ok := diffByKey[key]; ok && cachedDiff.ResourceVersion == resourceVersion {
307: 			dr = &diff.DiffResult{
308: 				NormalizedLive: []byte(cachedDiff.NormalizedLiveState),
309: 				PredictedLive:  []byte(cachedDiff.PredictedLiveState),
310: 				Modified:       cachedDiff.Modified,
311: 			}
312: 		} else {
313: 			res, err := diff.Diff(configArray[i], liveArray[i], opts...)
314: 			if err != nil {
315: 				return nil, err
316: 			}
317: 			dr = res
318: 		}
319: 		if dr != nil {
320: 			diffResultList.Diffs[i] = *dr
321: 			if dr.Modified {
322: 				diffResultList.Modified = true
323: 			}
324: 		}
325: 	}
326: 
327: 	return &diffResultList, nil
328: }
