330: // DiffFromCache will verify if it should retrieve the cached ResourceDiff based on this
331: // DiffConfig. Returns true and the cached ResourceDiff if configured to use the cache.
332: // Returns false and nil otherwise.
333: func (c *diffConfig) DiffFromCache(appName string) (bool, []*v1alpha1.ResourceDiff) {
334: 	if c.noCache || c.stateCache == nil || appName == "" {
335: 		return false, nil
336: 	}
337: 	cachedDiff := make([]*v1alpha1.ResourceDiff, 0)
338: 	if c.stateCache != nil && c.stateCache.GetAppManagedResources(appName, &cachedDiff) == nil {
339: 		return true, cachedDiff
340: 	}
341: 	return false, nil
342: }
343: 
344: // preDiffNormalize applies the normalization of live and target resources before invoking
345: // the diff. None of the attributes in the lives and targets params will be modified.
346: func preDiffNormalize(lives, targets []*unstructured.Unstructured, diffConfig DiffConfig) (*NormalizationResult, error) {
347: 	if diffConfig == nil {
348: 		return nil, fmt.Errorf("preDiffNormalize error: diffConfig can not be nil")
349: 	}
350: 	err := diffConfig.Validate()
351: 	if err != nil {
352: 		return nil, fmt.Errorf("preDiffNormalize error: %s", err)
353: 	}
354: 
355: 	results := &NormalizationResult{}
356: 	for i := range targets {
357: 		target := safeDeepCopy(targets[i])
358: 		live := safeDeepCopy(lives[i])
359: 		resourceTracking := argo.NewResourceTracking()
360: 		_ = resourceTracking.Normalize(target, live, diffConfig.AppLabelKey(), diffConfig.TrackingMethod())
361: 		// just normalize on managed fields if live and target aren't nil as we just care
362: 		// about conflicting fields
363: 		if live != nil && target != nil {
364: 			gvk := target.GetObjectKind().GroupVersionKind()
365: 			idc := NewIgnoreDiffConfig(diffConfig.Ignores(), diffConfig.Overrides())
366: 			ok, ignoreDiff := idc.HasIgnoreDifference(gvk.Group, gvk.Kind, target.GetName(), target.GetNamespace())
367: 			if ok && len(ignoreDiff.ManagedFieldsManagers) > 0 {
368: 				pt := scheme.ResolveParseableType(gvk, diffConfig.GVKParser())
369: 				var err error
370: 				live, target, err = managedfields.Normalize(live, target, ignoreDiff.ManagedFieldsManagers, pt)
371: 				if err != nil {
372: 					return nil, err
373: 				}
374: 			}
375: 		}
376: 		results.Lives = append(results.Lives, live)
377: 		results.Targets = append(results.Targets, target)
378: 	}
379: 	return results, nil
380: }
381: 
382: // safeDeepCopy will return nil if given obj is nil.
383: func safeDeepCopy(obj *unstructured.Unstructured) *unstructured.Unstructured {
384: 	if obj == nil {
385: 		return nil
386: 	}
387: 	return obj.DeepCopy()
388: }
