13: // Normalize will compare the live and config states. If config mutates
14: // a field that belongs to one of the trustedManagers it will remove
15: // that field from both live and config objects and return the normalized
16: // objects in this order. This function won't modify the live and config
17: // parameters. If pt is nil, the normalization will use a deduced parseable
18: // type which means that lists and maps are manipulated atomically.
19: // It is a no-op if no trustedManagers is provided. It is also a no-op if
20: // live or config are nil.
21: func Normalize(live, config *unstructured.Unstructured, trustedManagers []string, pt *typed.ParseableType) (*unstructured.Unstructured, *unstructured.Unstructured, error) {
22: 	if len(trustedManagers) == 0 {
23: 		return nil, nil, nil
24: 	}
25: 	if live == nil || config == nil {
26: 		return nil, nil, nil
27: 	}
28: 
29: 	liveCopy := live.DeepCopy()
30: 	configCopy := config.DeepCopy()
31: 	results, err := newTypedResults(liveCopy, configCopy, pt)
32: 	if err != nil {
33: 		return nil, nil, fmt.Errorf("error building typed results: %s", err)
34: 	}
35: 
36: 	normalized := false
37: 	for _, mf := range live.GetManagedFields() {
38: 		if trustedManager(mf.Manager, trustedManagers) {
39: 			err := normalize(mf, results)
40: 			if err != nil {
41: 				return nil, nil, fmt.Errorf("error normalizing manager %s: %s", mf.Manager, err)
42: 			}
43: 			normalized = true
44: 		}
45: 	}
46: 
47: 	if !normalized {
48: 		return liveCopy, configCopy, nil
49: 	}
50: 	lvu := results.live.AsValue().Unstructured()
51: 	l, ok := lvu.(map[string]interface{})
52: 	if !ok {
53: 		return nil, nil, fmt.Errorf("error converting live typedValue: expected map got %T", lvu)
54: 	}
55: 	normLive := &unstructured.Unstructured{Object: l}
56: 
57: 	cvu := results.config.AsValue().Unstructured()
58: 	c, ok := cvu.(map[string]interface{})
59: 	if !ok {
60: 		return nil, nil, fmt.Errorf("error converting config typedValue: expected map got %T", cvu)
61: 	}
62: 	normConfig := &unstructured.Unstructured{Object: c}
63: 	return normLive, normConfig, nil
64: }
