66: // normalize will check if the modified set has fields that are present
67: // in the managed fields entry. If so, it will remove the fields from
68: // the live and config objects so it is ignored in diffs.
69: func normalize(mf v1.ManagedFieldsEntry, tr *typedResults) error {
70: 	mfs := &fieldpath.Set{}
71: 	err := mfs.FromJSON(bytes.NewReader(mf.FieldsV1.Raw))
72: 	if err != nil {
73: 		return err
74: 	}
75: 	intersect := mfs.Intersection(tr.comparison.Modified)
76: 	if intersect.Empty() {
77: 		return nil
78: 	}
79: 	tr.live = tr.live.RemoveItems(intersect)
80: 	tr.config = tr.config.RemoveItems(intersect)
81: 	return nil
82: }
