102: 	}
103: 	comparison, err := typedLive.Compare(typedConfig)
104: 	if err != nil {
105: 		return nil, fmt.Errorf("error comparing typed resources: %s", err)
106: 	}
107: 	return &typedResults{
108: 		live:       typedLive,
109: 		config:     typedConfig,
110: 		comparison: comparison,
111: 	}, nil
112: }
