13: // Normalize will compare the live and config states. If config mutates
14: // a field that belongs to one of the trustedManagers it will remove
15: // that field from both live and config objects and return the normalized
16: // objects in this order. This function won't modify the live and config
17: // parameters. If pt is nil, the normalization will use a deduced parseable
18: // type which means that lists and maps are manipulated atomically.
19: // It is a no-op if no trustedManagers is provided. It is also a no-op if
20: // live or config are nil.
21: func Normalize(live, config *unstructured.Unstructured, trustedManagers []string, pt *typed.ParseableType) (*unstructured.Unstructured, *unstructured.Unstructured, error) {
22: 	if len(trustedManagers) == 0 {
23: 		return nil, nil, nil
24: 	}
25: 	if live == nil || config == nil {
26: 		return nil, nil, nil
27: 	}
28: 
29: 	liveCopy := live.DeepCopy()
30: 	configCopy := config.DeepCopy()
31: 	results, err := newTypedResults(liveCopy, configCopy, pt)
32: 	if err != nil {
33: 		return nil, nil, fmt.Errorf("error building typed results: %s", err)
34: 	}
35: 
36: 	normalized := false
37: 	for _, mf := range live.GetManagedFields() {
38: 		if trustedManager(mf.Manager, trustedManagers) {
39: 			err := normalize(mf, results)
40: 			if err != nil {
41: 				return nil, nil, fmt.Errorf("error normalizing manager %s: %s", mf.Manager, err)
42: 			}
43: 			normalized = true
44: 		}
45: 	}
46: 
47: 	if !normalized {
48: 		return liveCopy, configCopy, nil
49: 	}
50: 	lvu := results.live.AsValue().Unstructured()
51: 	l, ok := lvu.(map[string]interface{})
52: 	if !ok {
53: 		return nil, nil, fmt.Errorf("error converting live typedValue: expected map got %T", lvu)
54: 	}
55: 	normLive := &unstructured.Unstructured{Object: l}
56: 
57: 	cvu := results.config.AsValue().Unstructured()
58: 	c, ok := cvu.(map[string]interface{})
59: 	if !ok {
60: 		return nil, nil, fmt.Errorf("error converting config typedValue: expected map got %T", cvu)
61: 	}
62: 	normConfig := &unstructured.Unstructured{Object: c}
63: 	return normLive, normConfig, nil
64: }
65: 
66: // normalize will check if the modified set has fields that are present
67: // in the managed fields entry. If so, it will remove the fields from
68: // the live and config objects so it is ignored in diffs.
69: func normalize(mf v1.ManagedFieldsEntry, tr *typedResults) error {
70: 	mfs := &fieldpath.Set{}
71: 	err := mfs.FromJSON(bytes.NewReader(mf.FieldsV1.Raw))
72: 	if err != nil {
73: 		return err
74: 	}
75: 	intersect := mfs.Intersection(tr.comparison.Modified)
76: 	if intersect.Empty() {
77: 		return nil
78: 	}
79: 	tr.live = tr.live.RemoveItems(intersect)
80: 	tr.config = tr.config.RemoveItems(intersect)
81: 	return nil
82: }
83: 
84: type typedResults struct {
85: 	live       *typed.TypedValue
86: 	config     *typed.TypedValue
87: 	comparison *typed.Comparison
88: }
89: 
90: // newTypedResults will convert live and config into a TypedValue using the given pt
91: // and compare them. Returns a typedResults with the coverted types and the comparison.
92: // If pt is nil, will use the DeducedParseableType.
93: func newTypedResults(live, config *unstructured.Unstructured, pt *typed.ParseableType) (*typedResults, error) {
94: 	typedLive, err := pt.FromUnstructured(live.Object)
95: 	if err != nil {
96: 		return nil, fmt.Errorf("error creating typedLive: %s", err)
97: 	}
98: 
99: 	typedConfig, err := pt.FromUnstructured(config.Object)
100: 	if err != nil {
101: 		return nil, fmt.Errorf("error creating typedConfig: %s", err)
102: 	}
103: 	comparison, err := typedLive.Compare(typedConfig)
104: 	if err != nil {
105: 		return nil, fmt.Errorf("error comparing typed resources: %s", err)
106: 	}
107: 	return &typedResults{
108: 		live:       typedLive,
109: 		config:     typedConfig,
110: 		comparison: comparison,
111: 	}, nil
112: }
113: 
114: // trustedManager will return true if trustedManagers contains curManager.
115: // Returns false otherwise.
116: func trustedManager(curManager string, trustedManagers []string) bool {
117: 	for _, m := range trustedManagers {
118: 		if m == curManager {
119: 			return true
120: 		}
121: 	}
122: 	return false
123: }
