37: // NewKnownTypesNormalizer create a normalizer that re-format custom resource fields using built-in Kubernetes types.
38: func NewKnownTypesNormalizer(overrides map[string]v1alpha1.ResourceOverride) (*knownTypesNormalizer, error) {
39: 	normalizer := knownTypesNormalizer{typeFields: map[schema.GroupKind][]knownTypeField{}}
40: 	for key, override := range overrides {
41: 		group, kind, err := getGroupKindForOverrideKey(key)
42: 		if err != nil {
43: 			log.Warn(err)
44: 		}
45: 		gk := schema.GroupKind{Group: group, Kind: kind}
46: 		for _, f := range override.KnownTypeFields {
47: 			if err := normalizer.addKnownField(gk, f.Field, f.Type); err != nil {
48: 				log.Warnf("Failed to configure known field normalizer: %v", err)
49: 			}
50: 		}
51: 	}
52: 	normalizer.ensureDefaultCRDsConfigured()
53: 	return &normalizer, nil
54: }
