56: func (n *knownTypesNormalizer) ensureDefaultCRDsConfigured() {
57: 	rolloutGK := schema.GroupKind{Group: application.Group, Kind: "Rollout"}
58: 	if _, ok := n.typeFields[rolloutGK]; !ok {
59: 		n.typeFields[rolloutGK] = []knownTypeField{{
60: 			fieldPath: []string{"spec", "template", "spec"},
61: 			newFieldFn: func() interface{} {
62: 				return &v1.PodSpec{}
63: 			},
64: 		}}
65: 	}
66: }
