68: func (n *knownTypesNormalizer) addKnownField(gk schema.GroupKind, fieldPath string, typePath string) error {
69: 	newFieldFn, ok := knownTypes[typePath]
70: 	if !ok {
71: 		return fmt.Errorf("type '%s' is not supported", typePath)
72: 	}
73: 	n.typeFields[gk] = append(n.typeFields[gk], knownTypeField{
74: 		fieldPath:  strings.Split(fieldPath, "."),
75: 		newFieldFn: newFieldFn,
76: 	})
77: 	return nil
78: }
