80: func normalize(obj map[string]interface{}, field knownTypeField, fieldPath []string) error {
81: 	for i := range fieldPath {
82: 		if nestedField, ok, err := unstructured.NestedFieldNoCopy(obj, fieldPath[:i+1]...); err == nil && ok {
83: 			items, ok := nestedField.([]interface{})
84: 			if !ok {
85: 				continue
86: 			}
87: 			for j := range items {
88: 				item, ok := items[j].(map[string]interface{})
89: 				if !ok {
90: 					continue
91: 				}
92: 
93: 				subPath := fieldPath[i+1:]
94: 				if len(subPath) == 0 {
95: 					newItem, err := remarshal(item, field)
96: 					if err != nil {
97: 						return err
98: 					}
99: 					items[j] = newItem
100: 				} else {
101: 					if err = normalize(item, field, subPath); err != nil {
102: 						return err
103: 					}
104: 				}
105: 			}
106: 			return unstructured.SetNestedSlice(obj, items, fieldPath[:i+1]...)
107: 		}
108: 	}
109: 
110: 	if fieldVal, ok, err := unstructured.NestedFieldNoCopy(obj, fieldPath...); ok && err == nil {
111: 		newFieldVal, err := remarshal(fieldVal, field)
112: 		if err != nil {
113: 			return err
114: 		}
115: 		err = unstructured.SetNestedField(obj, newFieldVal, fieldPath...)
116: 		if err != nil {
117: 			return err
118: 		}
119: 	}
120: 
121: 	return nil
122: }
