124: func remarshal(fieldVal interface{}, field knownTypeField) (interface{}, error) {
125: 	data, err := json.Marshal(fieldVal)
126: 	if err != nil {
127: 		return nil, err
128: 	}
129: 	typedValue := field.newFieldFn()
130: 	err = json.Unmarshal(data, typedValue)
131: 	if err != nil {
132: 		return nil, err
133: 	}
134: 	data, err = json.Marshal(typedValue)
135: 	if err != nil {
